package tn.isims.cabinet.rmi.impl;

import tn.isims.cabinet.rmi.callback.PatientCallback;

import java.rmi.RemoteException;
import java.rmi.server.UnicastRemoteObject;
import java.util.ArrayList;
import java.util.List;

/**
 * Implémentation du callback patient
 * Cette classe est instanciée côté client (patient) pour recevoir les notifications
 */
public class PatientCallbackImpl extends UnicastRemoteObject implements PatientCallback {

    private static final long serialVersionUID = 1L;
    private final Long patientId;
    private final List<String> notifications = new ArrayList<>();

    public PatientCallbackImpl(Long patientId) throws RemoteException {
        super();
        this.patientId = patientId;
    }

    @Override
    public void recevoirNotification(String notification) throws RemoteException {
        System.out.println("=== NOTIFICATION REÇUE ===");
        System.out.println("Pour le patient ID: " + patientId);
        System.out.println("Message: " + notification);
        System.out.println("=========================");

        // Stocker la notification
        notifications.add(notification);

        // Log dans un fichier pour audit
        logNotification(notification);
    }

    @Override
    public Long getPatientId() throws RemoteException {
        return patientId;
    }

    /**
     * Récupère toutes les notifications reçues
     * @return Liste des notifications
     */
    public List<String> getNotifications() {
        return new ArrayList<>(notifications);
    }

    /**
     * Récupère les notifications non lues
     * @return Liste des notifications non lues
     */
    public List<String> getNotificationsNonLues() {
        return new ArrayList<>(notifications);
    }

    private void logNotification(String notification) {
        // Dans une vraie application, on écrirait dans un fichier de log
        // ou on enverrait vers une base de données
        System.out.println("[LOG] Notification enregistrée: " + notification);
    }
}

package tn.isims.cabinet.rmi.impl;

import tn.isims.cabinet.rmi.callback.PatientCallback;

import java.rmi.RemoteException;
import java.rmi.server.UnicastRemoteObject;
import java.io.Serial;
import java.util.ArrayList;
import java.util.List;
import java.util.Collections;

/**
 * Implémentation du callback patient
 * Cette classe est instanciée côté client (patient) pour recevoir les notifications
 */
public class PatientCallbackImpl extends UnicastRemoteObject implements PatientCallback {

    @Serial
    private static final long serialVersionUID = 1L;
    private final Long patientId;
    private final List<String> notifications = Collections.synchronizedList(new ArrayList<>());

    public PatientCallbackImpl(Long patientId) throws RemoteException {
        super();
        this.patientId = patientId;
    }

    @Override
    public void recevoirNotification(String notification) throws RemoteException {
        System.out.println("=== NOTIFICATION REÇUE ===");
        System.out.println("Pour le patient ID: " + patientId);
        System.out.println("Message: " + notification);
        System.out.println("=========================");

        // Stocker la notification
        notifications.add(notification);

        // Log dans un fichier pour audit
        logNotification(notification);
    }

    @Override
    public Long getPatientId() throws RemoteException {
        return patientId;
    }

    /**
     * Récupère toutes les notifications reçues
     * @return Liste des notifications
     */
    public List<String> getNotifications() {
        synchronized (notifications) {
            return new ArrayList<>(notifications);
        }
    }

    /**
     * Récupère les notifications non lues
     * @return Liste des notifications non lues
     */
    public List<String> getNotificationsNonLues() {
        synchronized (notifications) {
            List<String> copies = new ArrayList<>(notifications);
            notifications.clear();
            return copies;
        }
    }

    private void logNotification(String notification) {
        // Dans une vraie application, on écrirait dans un fichier de log
        // ou on enverrait vers une base de données
        System.out.println("[LOG] Notification enregistrée: " + notification);
    }
}

package tn.isims.cabinet.rmi.impl;

import tn.isims.cabinet.rmi.callback.PatientCallback;
import tn.isims.cabinet.rmi.impl.CabinetRMIServiceRemote;

import java.net.InetAddress;
import java.rmi.Naming;
import java.time.LocalDateTime;
import java.util.Scanner;

/**
 * Application cliente RMI pour les patients
 * Permet aux patients de se connecter et recevoir des notifications
 */
public class RMIClientApplication {

    private static final String SERVER_ADDRESS = "localhost";
    private static final int RMI_PORT = 1099;
    private static final String SERVICE_NAME = "CabinetRMIService";

    private CabinetRMIServiceRemote server;
    private PatientCallbackImpl callback;
    private Long patientId;

    public static void main(String[] args) {
        new RMIClientApplication().demarrer();
    }

    public void demarrer() {
        Scanner scanner = new Scanner(System.in);

        try {
            // Connexion au serveur
            System.out.println("=== Application Patient - Cabinet Médical ===");
            System.out.print("Entrez votre ID patient: ");
            patientId = scanner.nextLong();
            scanner.nextLine();

            // Créer le callback
            callback = new PatientCallbackImpl(patientId);

            // Rechercher le service sur le serveur
            String serviceUrl = "rmi://" + SERVER_ADDRESS + ":" + RMI_PORT + "/" + SERVICE_NAME;
            System.out.println("Connexion à: " + serviceUrl);

            server = (CabinetRMIServiceRemote) Naming.lookup(serviceUrl);

            // S'enregistrer pour les notifications
            boolean registered = server.sEnregistrerPourNotifications(patientId, callback);
            if (registered) {
                System.out.println("Enregistré avec succès! Vous recevrez les notifications.");
            }

            // Menu principal
            boolean running = true;
            while (running) {
                afficherMenu();
                int choix = scanner.nextInt();
                scanner.nextLine();

                switch (choix) {
                    case 1:
                        consulterRendezVous();
                        break;
                    case 2:
                        creerRendezVous(scanner);
                        break;
                    case 3:
                        modifierRendezVous(scanner);
                        break;
                    case 4:
                        annulerRendezVous(scanner);
                        break;
                    case 5:
                        voirNotifications();
                        break;
                    case 0:
                        running = false;
                        System.out.println("Au revoir!");
                        break;
                    default:
                        System.out.println("Option invalide");
                }
            }

        } catch (Exception e) {
            System.err.println("Erreur: " + e.getMessage());
            e.printStackTrace();
        }
    }

    private void afficherMenu() {
        System.out.println("\n--- Menu Patient ---");
        System.out.println("1. Consulter mes rendez-vous");
        System.out.println("2. Créer un rendez-vous");
        System.out.println("3. Modifier un rendez-vous");
        System.out.println("4. Annuler un rendez-vous");
        System.out.println("5. Voir mes notifications");
        System.out.println("0. Quitter");
        System.out.print("Votre choix: ");
    }

    private void consulterRendezVous() {
        try {
            var rendezVous = server.consulterRendezVousPassesEtFuturs(patientId);
            if (rendezVous.isEmpty()) {
                System.out.println("Aucun rendez-vous trouvé.");
            } else {
                rendezVous.forEach(System.out::println);
            }
        } catch (Exception e) {
            System.err.println("Erreur: " + e.getMessage());
        }
    }

    private void creerRendezVous(Scanner scanner) {
        try {
            System.out.print("ID Médecin: ");
            Long medecinId = scanner.nextLong();
            scanner.nextLine();

            System.out.print("Date (AAAA-MM-JJ HH:MM): ");
            String dateStr = scanner.nextLine();
            LocalDateTime date = LocalDateTime.parse(dateStr.replace(" ", "T"));

            System.out.print("Motif: ");
            String motif = scanner.nextLine();

            String result = server.creerRendezVousRMI(patientId, medecinId, date, motif);
            System.out.println(result);
        } catch (Exception e) {
            System.err.println("Erreur: " + e.getMessage());
        }
    }

    private void modifierRendezVous(Scanner scanner) {
        try {
            System.out.print("ID Rendez-vous: ");
            Long rdvId = scanner.nextLong();
            scanner.nextLine();

            System.out.print("Nouvelle date (AAAA-MM-JJ HH:MM): ");
            String dateStr = scanner.nextLine();
            LocalDateTime nouvelleDate = LocalDateTime.parse(dateStr.replace(" ", "T"));

            String result = server.modifierRendezVousRMI(rdvId, nouvelleDate);
            System.out.println(result);
        } catch (Exception e) {
            System.err.println("Erreur: " + e.getMessage());
        }
    }

    private void annulerRendezVous(Scanner scanner) {
        try {
            System.out.print("ID Rendez-vous à annuler: ");
            Long rdvId = scanner.nextLong();

            String result = server.annulerRendezVousRMI(rdvId);
            System.out.println(result);
        } catch (Exception e) {
            System.err.println("Erreur: " + e.getMessage());
        }
    }

    private void voirNotifications() {
        System.out.println("\n=== Mes Notifications ===");
        var notifications = callback.getNotifications();
        if (notifications.isEmpty()) {
            System.out.println("Aucune notification.");
        } else {
            notifications.forEach(n -> System.out.println("- " + n));
        }
    }
}

package tn.isims.cabinet.rmi.impl;

import tn.isims.cabinet.rmi.callback.PatientCallback;
import tn.isims.cabinet.rmi.impl.CabinetRMIServiceRemote;

import java.rmi.Naming;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.Scanner;

/**
 * Application cliente RMI pour les patients
 * Permet aux patients de se connecter et recevoir des notifications
 */
public class RMIClientApplication {

    private static final String SERVER_ADDRESS = "localhost";
    private static final int RMI_PORT = 1099;
    private static final String SERVICE_NAME = "CabinetRMIService";
    private static final DateTimeFormatter INPUT_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");

    private CabinetRMIServiceRemote server;
    private PatientCallbackImpl callback;
    private Long patientId;

    public static void main(String[] args) {
        new RMIClientApplication().demarrer();
    }

    public void demarrer() {
        try (Scanner scanner = new Scanner(System.in)) {
            String serviceUrl = "rmi://" + SERVER_ADDRESS + ":" + RMI_PORT + "/" + SERVICE_NAME;
            System.out.println("Connexion à: " + serviceUrl);

            try {
                server = (CabinetRMIServiceRemote) Naming.lookup(serviceUrl);
            } catch (Exception e) {
                System.err.println("Impossible de se connecter au service RMI : " + e.getMessage());
                System.err.println("Assurez-vous que le serveur RMI est en cours d'exécution.");
                return;
            }

            boolean continueApp = true;
            while (continueApp) {
                System.out.println("\n=== Application Patient - Cabinet Médical ===");
                patientId = lireLong(scanner, "Entrez votre ID patient: ");

                try {
                    callback = new PatientCallbackImpl(patientId);

                    boolean registered = server.sEnregistrerPourNotifications(patientId, callback);
                    if (registered) {
                        System.out.println("Enregistré avec succès ! Vous recevrez les notifications.");
                    } else {
                        System.out.println("Impossible d'activer les notifications pour le moment.");
                    }

                    boolean running = true;
                    while (running) {
                        afficherMenu();
                        int choix = lireChoixMenu(scanner);

                        switch (choix) {
                            case 1:
                                consulterRendezVous();
                                break;
                            case 2:
                                creerRendezVous(scanner);
                                break;
                            case 3:
                                modifierRendezVous(scanner);
                                break;
                            case 4:
                                annulerRendezVous(scanner);
                                break;
                            case 5:
                                voirNotifications();
                                break;
                            case 6:
                                running = false;
                                continueApp = gererQuitter(scanner);
                                break;
                            default:
                                System.out.println("Option invalide. Veuillez choisir un numéro entre 1 et 6.");
                        }

                        if (running) {
                            attendreRetourAuMenu(scanner);
                        }
                    }
                } catch (Exception e) {
                    System.err.println("Erreur lors de la session patient : " + e.getMessage());
                    e.printStackTrace();
                    continueApp = false;
                }
            }
        } catch (Exception e) {
            System.err.println("Échec du client RMI : " + e.getMessage());
            e.printStackTrace();
        }
    }

    private boolean gererQuitter(Scanner scanner) {
        System.out.println("\n--- Fin de session ---");
        System.out.println("1. Quitter l'application");
        System.out.println("2. Choisir un autre ID patient");
        System.out.print("Votre choix: ");

        String choix = scanner.nextLine().trim();
        if (choix.equals("1")) {
            System.out.println("Au revoir !");
            return false; // Exit application
        } else if (choix.equals("2")) {
            System.out.println(""); // Blank line for readability
            return true; // Go back to patient ID input
        } else {
            System.out.println("Option invalide. Quitter l'application par défaut.");
            System.out.println("Au revoir !");
            return false;
        }
    }

    private void afficherMenu() {
        System.out.println("\n--- Menu Patient ---");
        System.out.println("1. Consulter mes rendez-vous");
        System.out.println("2. Créer un rendez-vous");
        System.out.println("3. Modifier un rendez-vous");
        System.out.println("4. Annuler un rendez-vous");
        System.out.println("5. Voir mes notifications");
        System.out.println("6. Quitter");
        System.out.print("Votre choix: ");
    }

    private int lireChoixMenu(Scanner scanner) {
        while (true) {
            String saisie = scanner.nextLine().trim();
            try {
                return Integer.parseInt(saisie);
            } catch (NumberFormatException e) {
                System.out.print("Veuillez saisir un nombre entre 1 et 6: ");
            }
        }
    }

    private Long lireLong(Scanner scanner, String message) {
        while (true) {
            System.out.print(message);
            String saisie = scanner.nextLine().trim();
            if (saisie.isEmpty()) {
                System.out.println("La valeur ne peut pas être vide.");
                continue;
            }
            try {
                return Long.parseLong(saisie);
            } catch (NumberFormatException e) {
                System.out.println("Veuillez saisir un identifiant numérique valide.");
            }
        }
    }

    private LocalDateTime lireDateHeure(Scanner scanner, String message) {
        while (true) {
            System.out.print(message);
            String saisie = scanner.nextLine().trim();
            if (saisie.isEmpty()) {
                System.out.println("La date ne peut pas être vide. Format attendu : yyyy-MM-dd HH:mm");
                continue;
            }
            try {
                return LocalDateTime.parse(saisie, INPUT_FORMATTER);
            } catch (DateTimeParseException e) {
                System.out.println("Format invalide. Utilisez le format yyyy-MM-dd HH:mm (ex: 2026-05-05 14:30).");
            }
        }
    }

    private String lireTexteObligatoire(Scanner scanner, String message) {
        while (true) {
            System.out.print(message);
            String saisie = scanner.nextLine().trim();
            if (!saisie.isEmpty()) {
                return saisie;
            }
            System.out.println("Cette valeur est obligatoire.");
        }
    }

    private void consulterRendezVous() {
        try {
            var rendezVous = server.consulterRendezVousPassesEtFuturs(patientId);
            if (rendezVous.isEmpty()) {
                System.out.println("Aucun rendez-vous trouvé.");
            } else {
                rendezVous.forEach(System.out::println);
            }
        } catch (Exception e) {
            System.err.println("Erreur lors de la consultation des rendez-vous : " + e.getMessage());
        }
    }

    private void creerRendezVous(Scanner scanner) {
        try {
            // Step 1: List all available doctors
            System.out.println("\n--- Sélectionner un médecin ---");
            var medecins = server.listerTousLesMedecins();

            if (medecins.isEmpty()) {
                System.out.println("❌ Aucun médecin disponible.");
                return;
            }

            // Display doctors with numbers for easy selection
            for (int i = 0; i < medecins.size(); i++) {
                System.out.printf("%d. Dr. %s (%s)\n", i + 1, 
                    medecins.get(i).getNom(), 
                    medecins.get(i).getSpecialite());
            }

            // Get doctor selection
            System.out.print("Sélectionnez un médecin (1-" + medecins.size() + "): ");
            int choice = lireChoixMenu(scanner);

            if (choice < 1 || choice > medecins.size()) {
                System.out.println("Selection invalide.");
                return;
            }

            Long medecinId = medecins.get(choice - 1).getId();

            // Step 2: Get date and reason
            LocalDateTime date = lireDateHeure(scanner, "Date du rendez-vous (yyyy-MM-dd HH:mm): ");
            String motif = lireTexteObligatoire(scanner, "Motif de la consultation: ");

            System.out.println("Création du rendez-vous en cours...");
            String result = server.creerRendezVousRMI(patientId, medecinId, date, motif);
            System.out.println(result);
        } catch (Exception e) {
            System.err.println("❌ Impossible de créer le rendez-vous : " + e.getMessage());
            e.printStackTrace();
        }
    }

    private void modifierRendezVous(Scanner scanner) {
        try {
            // Step 1: List all patient's rendez-vous
            System.out.println("\n--- Vos rendez-vous ---");
            var rendezVous = server.consulterRendezVousPassesEtFuturs(patientId);

            if (rendezVous.isEmpty()) {
                System.out.println("Aucun rendez-vous trouvé.");
                return;
            }

            // Display rendez-vous with numbers for easy selection
            for (int i = 0; i < rendezVous.size(); i++) {
                var rdv = rendezVous.get(i);
                System.out.printf("%d. RDV #%d - %s avec Dr. %s (Motif: %s)\n", 
                    i + 1, rdv.getId(), rdv.getDateRendezVous(),
                    rdv.getMedecin().getNom(), rdv.getMotif());
            }

            // Get selection
            System.out.print("Sélectionnez un rendez-vous à modifier (1-" + rendezVous.size() + "): ");
            int choice = lireChoixMenu(scanner);

            if (choice < 1 || choice > rendezVous.size()) {
                System.out.println("Selection invalide.");
                return;
            }

            Long rdvId = rendezVous.get(choice - 1).getId();

            // Step 2: Get new date
            LocalDateTime nouvelleDate = lireDateHeure(scanner, "Nouvelle date (yyyy-MM-dd HH:mm): ");

            String result = server.modifierRendezVousRMI(rdvId, nouvelleDate);
            System.out.println(result);
        } catch (Exception e) {
            System.err.println("❌ Impossible de modifier le rendez-vous : " + e.getMessage());
            e.printStackTrace();
        }
    }

    private void annulerRendezVous(Scanner scanner) {
        try {
            // Step 1: List all patient's rendez-vous
            System.out.println("\n--- Vos rendez-vous ---");
            var rendezVous = server.consulterRendezVousPassesEtFuturs(patientId);

            if (rendezVous.isEmpty()) {
                System.out.println("Aucun rendez-vous trouvé.");
                return;
            }

            // Display rendez-vous with numbers for easy selection
            for (int i = 0; i < rendezVous.size(); i++) {
                var rdv = rendezVous.get(i);
                System.out.printf("%d. RDV #%d - %s avec Dr. %s (Motif: %s)\n", 
                    i + 1, rdv.getId(), rdv.getDateRendezVous(),
                    rdv.getMedecin().getNom(), rdv.getMotif());
            }

            // Get selection
            System.out.print("Sélectionnez un rendez-vous à annuler (1-" + rendezVous.size() + "): ");
            int choice = lireChoixMenu(scanner);

            if (choice < 1 || choice > rendezVous.size()) {
                System.out.println("Selection invalide.");
                return;
            }

            Long rdvId = rendezVous.get(choice - 1).getId();

            String result = server.annulerRendezVousRMI(rdvId);
            System.out.println(result);
        } catch (Exception e) {
            System.err.println("❌ Impossible d'annuler le rendez-vous : " + e.getMessage());
            e.printStackTrace();
        }
    }

    private void voirNotifications() {
        System.out.println("\n=== Mes Notifications ===");
        if (callback == null) {
            System.out.println("Aucune session de notifications n'est disponible.");
            return;
        }

        var notifications = callback.getNotifications();
        if (notifications.isEmpty()) {
            System.out.println("Aucune notification.");
        } else {
            notifications.forEach(n -> System.out.println("- " + n));
            System.out.println("--- Fin des notifications ---");
        }
    }

    private void attendreRetourAuMenu(Scanner scanner) {
        System.out.print("\nAppuyez sur Entrée pour revenir au menu...");
        scanner.nextLine();
    }
}

package tn.isims.cabinet.servlet;

import jakarta.ejb.EJB;
import jakarta.servlet.ServletException;
import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.HttpServlet;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import tn.isims.cabinet.ejb.medecin.MedecinServiceLocal;
import tn.isims.cabinet.entity.Medecin;
import tn.isims.cabinet.entity.Patient;

import java.io.IOException;
import java.util.List;

/**
 * Servlet pour la gestion des médecins
 */
@WebServlet({"/medecins", "/medecins/*"})
public class MedecinServlet extends HttpServlet {

    private static final long serialVersionUID = 1L;

    @EJB(beanName = "MedecinService")
    private MedecinServiceLocal medecinService;

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        String pathInfo = request.getPathInfo();
        String action = pathInfo != null ? pathInfo.substring(1) : "";

        switch (action) {
            case "add":
                afficherFormulaireAjout(request, response);
                break;
            case "edit":
                afficherFormulaireModification(request, response);
                break;
            case "search":
                rechercherParSpecialite(request, response);
                break;
            case "patients":
                afficherPatientsDuMedecin(request, response);
                break;
            case "delete":
                supprimerMedecin(request, response);
                break;
            default:
                listerMedecins(request, response);
        }
    }

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        String pathInfo = request.getPathInfo();
        String pathAction = (pathInfo != null && pathInfo.length() > 1) ? pathInfo.substring(1) : "";
        String paramAction = request.getParameter("action");
        String action = !pathAction.isEmpty() ? pathAction : (paramAction != null ? paramAction : "");

        switch (action) {
            case "add":
            case "save":
                sauvegarderMedecin(request, response);
                break;
            case "delete":
                supprimerMedecin(request, response);
                break;
            default:
                response.sendRedirect(request.getContextPath() + "/medecins");
        }
    }

    private void listerMedecins(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        List<Medecin> medecins = medecinService.listerTousLesMedecins();
        List<String> specialites = medecinService.listerSpecialites();

        request.setAttribute("medecins", medecins);
        request.setAttribute("specialites", specialites);
        request.getRequestDispatcher("/WEB-INF/views/medecins/liste.jsp").forward(request, response);
    }

    private void rechercherParSpecialite(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        String specialite = request.getParameter("specialite");
        List<Medecin> medecins;

        if (specialite != null && !specialite.trim().isEmpty()) {
            medecins = medecinService.rechercherParSpecialite(specialite);
        } else {
            medecins = medecinService.listerTousLesMedecins();
        }

        List<String> specialites = medecinService.listerSpecialites();

        request.setAttribute("medecins", medecins);
        request.setAttribute("specialites", specialites);
        request.setAttribute("specialiteSelectionnee", specialite);
        request.getRequestDispatcher("/WEB-INF/views/medecins/liste.jsp").forward(request, response);
    }

    private void afficherPatientsDuMedecin(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        String idStr = request.getParameter("id");
        if (idStr != null) {
            Long id = Long.parseLong(idStr);
            Medecin medecin = medecinService.trouverMedecinParId(id);
            List<Patient> patients = medecinService.obtenirPatientsDuMedecin(id);

            request.setAttribute("medecin", medecin);
            request.setAttribute("patients", patients);
            request.getRequestDispatcher("/WEB-INF/views/medecins/patients.jsp").forward(request, response);
        } else {
            response.sendRedirect(request.getContextPath() + "/medecins");
        }
    }

    private void afficherFormulaireAjout(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        request.getRequestDispatcher("/WEB-INF/views/medecins/ajouter.jsp").forward(request, response);
    }

    private void afficherFormulaireModification(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        String idStr = request.getParameter("id");
        if (idStr != null) {
            Long id = Long.parseLong(idStr);
            Medecin medecin = medecinService.trouverMedecinParId(id);
            request.setAttribute("medecin", medecin);
        }
        request.getRequestDispatcher("/WEB-INF/views/medecins/modifier.jsp").forward(request, response);
    }

    private void sauvegarderMedecin(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        try {
            String idStr = request.getParameter("id");
            String nom = request.getParameter("nom");
            String prenom = request.getParameter("prenom");
            String specialite = request.getParameter("specialite");
            String email = request.getParameter("email");

            if (idStr == null || idStr.isEmpty()) {
                // Ajout d'un nouveau médecin
                Medecin medecin = new Medecin(nom, prenom, specialite, email);
                medecinService.ajouterMedecin(medecin);
                request.setAttribute("message", "Médecin ajouté avec succès!");
            } else {
                // Modification
                Long id = Long.parseLong(idStr);
                Medecin medecinModifie = new Medecin(nom, prenom, specialite, email);
                medecinService.modifierMedecin(id, medecinModifie);
                request.setAttribute("message", "Médecin modifié avec succès!");
            }
        } catch (Exception e) {
            request.setAttribute("erreur", "Erreur: " + e.getMessage());
        }

        response.sendRedirect(request.getContextPath() + "/medecins");
    }

    private void supprimerMedecin(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        String idStr = request.getParameter("id");
        if (idStr != null) {
            Long id = Long.parseLong(idStr);
            boolean success = medecinService.supprimerMedecin(id);

            if (success) {
                request.setAttribute("message", "Médecin supprimé avec succès!");
            } else {
                request.setAttribute("erreur", "Impossible de supprimer: médecin avec des rendez-vous");
            }
        }

        response.sendRedirect(request.getContextPath() + "/medecins");
    }
}

package tn.isims.cabinet.servlet;

import jakarta.ejb.EJB;
import jakarta.servlet.ServletException;
import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.HttpServlet;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import jakarta.servlet.http.HttpSession;
import tn.isims.cabinet.ejb.medecin.MedecinServiceLocal;
import tn.isims.cabinet.entity.Medecin;
import tn.isims.cabinet.entity.Patient;

import java.io.IOException;
import java.util.List;

/**
 * Servlet pour la gestion des médecins
 */
@WebServlet({"/medecins", "/medecins/*"})
public class MedecinServlet extends HttpServlet {

    private static final long serialVersionUID = 1L;

    @EJB(beanName = "MedecinService")
    private MedecinServiceLocal medecinService;

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        try {
            String pathInfo = request.getPathInfo();
            String action = pathInfo != null ? pathInfo.substring(1) : "";

            switch (action) {
                case "add":
                    afficherFormulaireAjout(request, response);
                    break;
                case "edit":
                    afficherFormulaireModification(request, response);
                    break;
                case "search":
                    rechercherParSpecialite(request, response);
                    break;
                case "patients":
                    afficherPatientsDuMedecin(request, response);
                    break;
                case "delete":
                    supprimerMedecin(request, response);
                    break;
                default:
                    listerMedecins(request, response);
            }
        } catch (Exception e) {
            handleError(request, response, "Erreur lors du chargement des médecins : " + e.getMessage());
        }
    }

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        try {
            String pathInfo = request.getPathInfo();
            String pathAction = (pathInfo != null && pathInfo.length() > 1) ? pathInfo.substring(1) : "";
            String paramAction = request.getParameter("action");
            String action = !pathAction.isEmpty() ? pathAction : (paramAction != null ? paramAction : "");

            switch (action) {
                case "add":
                case "save":
                case "edit":
                    sauvegarderMedecin(request, response);
                    break;
                case "delete":
                    supprimerMedecin(request, response);
                    break;
                default:
                    response.sendRedirect(request.getContextPath() + "/medecins");
            }
        } catch (Exception e) {
            handleError(request, response, "Erreur lors du traitement du médecin : " + e.getMessage());
        }
    }

    private void listerMedecins(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        List<Medecin> medecins = medecinService.listerTousLesMedecins();
        List<String> specialites = medecinService.listerSpecialites();

        request.setAttribute("medecins", medecins);
        request.setAttribute("specialites", specialites);
        request.getRequestDispatcher("/WEB-INF/views/medecins/liste.jsp").forward(request, response);
    }

    private void rechercherParSpecialite(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        String specialite = request.getParameter("specialite");
        List<Medecin> medecins;

        if (specialite != null && !specialite.trim().isEmpty()) {
            medecins = medecinService.rechercherParSpecialite(specialite);
        } else {
            medecins = medecinService.listerTousLesMedecins();
        }

        List<String> specialites = medecinService.listerSpecialites();

        request.setAttribute("medecins", medecins);
        request.setAttribute("specialites", specialites);
        request.setAttribute("specialiteSelectionnee", specialite);
        request.getRequestDispatcher("/WEB-INF/views/medecins/liste.jsp").forward(request, response);
    }

    private void afficherPatientsDuMedecin(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        String idStr = request.getParameter("id");
        if (idStr == null || idStr.isBlank()) {
            flash(request, "error", "Identifiant du médecin manquant.");
            response.sendRedirect(request.getContextPath() + "/medecins");
            return;
        }

        Long id;
        try {
            id = Long.parseLong(idStr);
        } catch (NumberFormatException e) {
            flash(request, "error", "Identifiant du médecin invalide.");
            response.sendRedirect(request.getContextPath() + "/medecins");
            return;
        }

        System.out.println("[MedecinServlet] Fetching patients for medecinId=" + id);
        Medecin medecin = medecinService.trouverMedecinParId(id);
        if (medecin == null) {
            flash(request, "error", "Médecin introuvable.");
            response.sendRedirect(request.getContextPath() + "/medecins");
            return;
        }

        List<Patient> patients = medecinService.obtenirPatientsDuMedecin(id);
        request.setAttribute("medecin", medecin);
        request.setAttribute("patients", patients);
        request.getRequestDispatcher("/WEB-INF/views/medecins/patients.jsp").forward(request, response);
    }

    private void afficherFormulaireAjout(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        request.getRequestDispatcher("/WEB-INF/views/medecins/ajouter.jsp").forward(request, response);
    }

    private void afficherFormulaireModification(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        String idStr = request.getParameter("id");
        if (idStr == null || idStr.isBlank()) {
            flash(request, "error", "Identifiant du médecin manquant.");
            response.sendRedirect(request.getContextPath() + "/medecins");
            return;
        }

        Long id;
        try {
            id = Long.parseLong(idStr);
        } catch (NumberFormatException e) {
            flash(request, "error", "Identifiant du médecin invalide.");
            response.sendRedirect(request.getContextPath() + "/medecins");
            return;
        }

        Medecin medecin = medecinService.trouverMedecinParId(id);
        if (medecin == null) {
            flash(request, "error", "Médecin introuvable.");
            response.sendRedirect(request.getContextPath() + "/medecins");
            return;
        }

        request.setAttribute("medecin", medecin);
        request.getRequestDispatcher("/WEB-INF/views/medecins/modifier.jsp").forward(request, response);
    }

    private void sauvegarderMedecin(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        String idStr = request.getParameter("id");
        boolean editing = idStr != null && !idStr.isBlank();
        Medecin medecinForm = buildMedecinFromRequest(request);
        if (editing && idStr != null && !idStr.isBlank()) {
            try {
                medecinForm.setId(Long.parseLong(idStr));
            } catch (NumberFormatException ignored) {
                // Keep the form usable even if the id is invalid.
            }
        }

        try {
            if (!editing) {
                System.out.println("[MedecinServlet] Adding medecin: " + medecinForm.getPrenom() + " " + medecinForm.getNom());
                medecinService.ajouterMedecin(medecinForm);
                flash(request, "success", "Médecin ajouté avec succès !");
                response.sendRedirect(request.getContextPath() + "/medecins");
            } else {
                Long id = Long.parseLong(idStr);
                System.out.println("[MedecinServlet] Updating medecin id=" + id + " : " + medecinForm.getPrenom() + " " + medecinForm.getNom());
                Medecin medecin = medecinService.modifierMedecin(id, medecinForm);
                if (medecin == null) {
                    request.setAttribute("erreur", "Médecin introuvable.");
                    request.setAttribute("medecin", medecinForm);
                    request.getRequestDispatcher("/WEB-INF/views/medecins/modifier.jsp").forward(request, response);
                    return;
                }
                flash(request, "success", "Médecin modifié avec succès !");
                response.sendRedirect(request.getContextPath() + "/medecins");
            }
        } catch (Exception e) {
            request.setAttribute("erreur", "Erreur: " + e.getMessage());
            request.setAttribute("medecin", medecinForm);
            if (editing) {
                request.getRequestDispatcher("/WEB-INF/views/medecins/modifier.jsp").forward(request, response);
            } else {
                request.getRequestDispatcher("/WEB-INF/views/medecins/ajouter.jsp").forward(request, response);
            }
        }
    }

    private Medecin buildMedecinFromRequest(HttpServletRequest request) {
        return new Medecin(
            request.getParameter("nom"),
            request.getParameter("prenom"),
            request.getParameter("specialite"),
            request.getParameter("email")
        );
    }

    private void supprimerMedecin(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        String idStr = request.getParameter("id");
        if (idStr == null || idStr.isBlank()) {
            flash(request, "error", "Identifiant du médecin manquant.");
            response.sendRedirect(request.getContextPath() + "/medecins");
            return;
        }

        try {
            Long id = Long.parseLong(idStr);
            boolean success = medecinService.supprimerMedecin(id);

            if (success) {
                flash(request, "success", "Médecin supprimé avec succès !");
            } else {
                flash(request, "error", "Impossible de supprimer: médecin avec des rendez-vous");
            }
            response.sendRedirect(request.getContextPath() + "/medecins");
        } catch (NumberFormatException e) {
            flash(request, "error", "Identifiant du médecin invalide.");
            response.sendRedirect(request.getContextPath() + "/medecins");
        }
    }

    private void flash(HttpServletRequest request, String type, String message) {
        HttpSession session = request.getSession();
        session.setAttribute("flashType", type);
        session.setAttribute("flashMessage", message);
    }

    private void handleError(HttpServletRequest request, HttpServletResponse response, String message)
            throws IOException {
        System.out.println("[MedecinServlet] " + message);
        flash(request, "error", message);
        response.sendRedirect(request.getContextPath() + "/medecins");
    }
}

package tn.isims.cabinet.servlet;

import jakarta.ejb.EJB;
import jakarta.servlet.ServletException;
import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.HttpServlet;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import jakarta.servlet.http.HttpSession;
import tn.isims.cabinet.ejb.patient.PatientServiceLocal;
import tn.isims.cabinet.entity.Patient;

import java.io.IOException;
import java.time.LocalDate;
import java.util.List;

@WebServlet({"/patients", "/patients/*"})
public class PatientServlet extends HttpServlet {

    private static final long serialVersionUID = 1L;

    @EJB(beanName = "PatientService")
    private PatientServiceLocal patientService;

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse res)
            throws ServletException, IOException {
        transferFlash(req);
        String pathInfo = req.getPathInfo();
        String action = (pathInfo != null && pathInfo.length() > 1) ? pathInfo.substring(1) : "";

        switch (action) {
            case "add":    afficherFormulaireAjout(req, res); break;
            case "edit":   afficherFormulaireModification(req, res); break;
            case "search": rechercherPatients(req, res); break;
            default:       listerPatients(req, res);
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse res)
            throws ServletException, IOException {
        String pathInfo = req.getPathInfo();
        String action = (pathInfo != null && pathInfo.length() > 1)
            ? pathInfo.substring(1)
            : req.getParameter("action") != null ? req.getParameter("action") : "";

        switch (action) {
            case "add":
            case "save":   sauvegarderPatient(req, res); break;
            case "edit":   sauvegarderPatient(req, res); break;
            case "delete": supprimerPatient(req, res); break;
            default:       res.sendRedirect(req.getContextPath() + "/patients");
        }
    }

    private void listerPatients(HttpServletRequest req, HttpServletResponse res)
            throws ServletException, IOException {
        req.setAttribute("patients", patientService.listerTousLesPatients());
        req.getRequestDispatcher("/WEB-INF/views/patients/liste.jsp").forward(req, res);
    }

    private void rechercherPatients(HttpServletRequest req, HttpServletResponse res)
            throws ServletException, IOException {
        String recherche = req.getParameter("recherche");
        List<Patient> patients = (recherche != null && !recherche.trim().isEmpty())
            ? patientService.rechercherParNomOuEmail(recherche)
            : patientService.listerTousLesPatients();
        req.setAttribute("patients", patients);
        req.setAttribute("recherche", recherche);
        req.getRequestDispatcher("/WEB-INF/views/patients/liste.jsp").forward(req, res);
    }

    private void afficherFormulaireAjout(HttpServletRequest req, HttpServletResponse res)
            throws ServletException, IOException {
        req.getRequestDispatcher("/WEB-INF/views/patients/ajouter.jsp").forward(req, res);
    }

    private void afficherFormulaireModification(HttpServletRequest req, HttpServletResponse res)
            throws ServletException, IOException {
        String idStr = req.getParameter("id");
        if (idStr != null) {
            Patient p = patientService.trouverPatientParId(Long.parseLong(idStr));
            req.setAttribute("patient", p);
        }
        req.getRequestDispatcher("/WEB-INF/views/patients/modifier.jsp").forward(req, res);
    }

    private void sauvegarderPatient(HttpServletRequest req, HttpServletResponse res)
            throws IOException {
        try {
            String idStr = req.getParameter("id");
            String nom = req.getParameter("nom");
            String prenom = req.getParameter("prenom");
            String email = req.getParameter("email");
            String telephone = req.getParameter("telephone");
            String dateStr = req.getParameter("dateNaissance");
            LocalDate dateNaissance = (dateStr != null && !dateStr.isEmpty()) ? LocalDate.parse(dateStr) : null;

            if (idStr == null || idStr.isEmpty()) {
                patientService.ajouterPatient(new Patient(nom, prenom, email, telephone, dateNaissance));
                flash(req, "success", "Patient ajouté avec succès !");
            } else {
                patientService.modifierPatient(Long.parseLong(idStr),
                    new Patient(nom, prenom, email, telephone, dateNaissance));
                flash(req, "success", "Patient modifié avec succès !");
            }
        } catch (Exception e) {
            flash(req, "error", "Erreur : " + e.getMessage());
        }
        res.sendRedirect(req.getContextPath() + "/patients");
    }

    private void supprimerPatient(HttpServletRequest req, HttpServletResponse res)
            throws IOException {
        String idStr = req.getParameter("id");
        if (idStr != null) {
            boolean ok = patientService.supprimerPatient(Long.parseLong(idStr));
            if (ok) flash(req, "success", "Patient supprimé avec succès !");
            else flash(req, "error", "Impossible : ce patient a des rendez-vous actifs.");
        }
        res.sendRedirect(req.getContextPath() + "/patients");
    }

    private void flash(HttpServletRequest req, String type, String msg) {
        req.getSession().setAttribute("flashMessage", msg);
        req.getSession().setAttribute("flashType", type);
    }

    private void transferFlash(HttpServletRequest req) {
        HttpSession s = req.getSession(false);
        if (s != null) {
            String msg = (String) s.getAttribute("flashMessage");
            String type = (String) s.getAttribute("flashType");
            if (msg != null) {
                if ("error".equals(type)) req.setAttribute("erreur", msg);
                else req.setAttribute("message", msg);
                s.removeAttribute("flashMessage");
                s.removeAttribute("flashType");
            }
        }
    }
}

